scwin.vScrenID = "ULDSTF35403.xml";
scwin.gWorkDD;
scwin.userParam;
scwin.testDateSet;
scwin.svrGubun = js_svrGubun; //DR전환시
scwin.gDepCd;
scwin.gEmpNo;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    var urldep = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD_1.DataID = encodeURI(urldep);
    dts_DEP_CD_1.Reset();
    var urlemp = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO_1.DataID = encodeURI(urlemp);
    dts_EMP_NO_1.Reset();

    //setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;		
    //setObjectValue(cmb_EMP_NO_1, js_emp_no) ;	
    $c.stf.setObjectValue(cmb_DEP_CD_1, '');
    $c.stf.setObjectValue(cmb_EMP_NO_1, '');
};
scwin.fn_set_trstatcd = function() {
    $c.stf.setObjectValue(txb_TR_STATE_CD, $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.stf.getObjectValue(edt_BASE_DD), "2"));
    $c.stf.setObjectValue(txb_ATS_STATE_CD, $c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, $c.stf.getObjectValue(edt_BASE_DD), "3"));
};
scwin.fn_WorkDD = function() {
    var url2 = "/listingCommon.do?method=listGeneral" + "&outputMessageId=MKT_HCALND_DD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_workday.select" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD);
    dts_WorkDD.DataID = encodeURI(url2);
    dts_WorkDD.reset();
    scwin.gWorkDD = dts_WorkDD.getCellData(1, "CALND_DD");
};


//거래량 요건  검색 
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_TERM) < 1) {
        $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    img_search.setDisabled(true);
    img_search.src = "../img/btn_select_d.gif";
    if (scwin.svrGubun == "dr") {
        //DR일 경우 2011.01.28
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }
    scwin.fn_WorkDD();
    var url = "";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.cmstk.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param16=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param17=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param18=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param19=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param20=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param21=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    } else {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.knstk.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param16=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param17=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param18=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param19=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param20=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param21=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    }
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기

};
scwin.fn_print = function() {
    scwin.fn_WorkDD();
    var url = "";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_PRINT_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.cmstk.print.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param16=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param17=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param18=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    } else {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_PRINT_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.knstk.print.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param16=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param17=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param18=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    }
    dts_report.DataID = encodeURI(url);
    dts_report.reset();
    if (dts_report.getTotalRow() <= 0) {
        $c.win.alert("인쇄할 항목이 없습니다.");
    } else {
        var pdf_rptname = "RLDSTF00028";
        var dataFormatArr = ["TOT_LIST_SHRS:FormatNumberEx", "PARVAL:FormatNumberEx", "BASE_TRDVOL:FormatNumberEx", "TOT_TR_VL_1:FormatNumberEx", "TOT_TR_VL_2:FormatNumberEx", "TOT_TR_VL_3:FormatNumberEx", "TOT_TR_VL_SUM:FormatNumberEx", "AVG_TR_VL:FormatNumberEx", "AVG_TR_VL_5000:FormatNumberEx", "CONV_MM1_AVG_TNOV_RT:FormatTofixed3"];
        var jsonData = $c.rpt.fn_make_dtsToJson1_wdf(dts_report, dataFormatArr);
        var userParam = [{
            uid: "BASE_DD",
            unm: $c.stf.FormatDateEx($c.stf.getObjectValue(edt_BASE_DD))
        }, {
            uid: "TERM",
            unm: $c.stf.getObjectValue(rdo_TERM) + "개월"
        }, {
            uid: "STATE",
            unm: $c.stf.getObjectValue(txb_TR_STATE_CD)
        }, {
            uid: "jsonData",
            unm: jsonData
        }, {
            uid: "horizontal",
            unm: "y"
        }];

        //PDF Convert
        $c.rpt.fn_open_report_pdf(pdf_rptname, scwin.userParam);
    }
};




