scwin.fn_print_old = function() {
    scwin.fn_WorkDD();
    var url = "";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_PRINT_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.cmstk.print.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param16=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param17=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param18=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    } else {
        url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA_PRINT_KOSDAQ" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.kosdaq.knstk.print.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 상장구분
            "&{P}param06=" + scwin.gWorkDD + "&{P}param07=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param10=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param11=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param12=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param13=" + $c.stf.getObjectValue(rdo_TERM) + "&{P}param14=" + $c.stf.getObjectValue(edt_BASE_DD) + // 기준일
            "&{P}param15=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param16=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param17=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param18=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    }
    dts_report.DataID = encodeURI(url);
    dts_report.reset();
    if (dts_report.getTotalRow() <= 0) {
        $c.win.alert("인쇄할 항목이 없습니다.");
    } else {
        scwin.userParam = [{
            uid: "BASE_DD",
            unm: $c.stf.getObjectValue(edt_BASE_DD)
        }, {
            uid: "TERM",
            unm: $c.stf.getObjectValue(rdo_TERM) + "개월"
        }, {
            uid: "STATE",
            unm: $c.stf.getObjectValue(txb_TR_STATE_CD)
        }];
        rex_rptname = "RLDSTF00028";
        //서브리포트섹션에 들어갈 값은 dataset를 하나더 만들어야 함
        //rex_gfGetGauceCsvStr(dts_report) : 상위
        //rex_gfGetGauceCsvStr(dts_report, dts_report_1) : 상위, 서브

        scwin.testDateSet = rex_gfGetGauceCsvStr(dts_List, dts_report);
        $c.rpt.fn_open_report(scwin.testDateSet, rex_rptname, scwin.userParam);
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		
    img_search.setDisabled(false);
    img_search.src = "../img/btn_select.gif";
};
scwin.dts_TR_STATE_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_TR_STATE_CD);
};
scwin.dts_List_OnLoadError = function() {
    //alert_error(dts_List);
    $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
    $c.cm.CloseWin(0, grd_List); //데이터 로딩중닫기 및 조회없음 처리
    img_search.setDisabled(false);
    img_search.src = "../img/btn_select.gif";
};
scwin.dts_WorkDD_OnLoadError = function() {
    $c.stf.alert_error(dts_WorkDD);
};
scwin.img_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.img_toExcel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List, "보통주거래현황 -거래량요건 목록", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_List, "종류주식거래현황 -거래량요건 목록", "", "8");
    }
};
scwin.img_search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Print_onclick = function() {
    scwin.fn_print();
};
scwin.dts_DEP_CD_1_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;
    $c.stf.setObjectValue(cmb_DEP_CD_1, '');
};
scwin.dts_EMP_NO_1_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EMP_NO_1, js_emp_no) ;
    $c.stf.setObjectValue(cmb_EMP_NO_1, '');
};
scwin.cmb_DEP_CD_1_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD_1);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO_1, '');
    }
    dts_EMP_NO_1.UseFilter = true;
    dts_EMP_NO_1.Filter();
    dts_EMP_NO_1.sort("DEP_CD", 0);
    //dts_EMP_NO_1.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_1_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO_1.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.grd_List_OnUserColor = function(row, eventId) {
    if (eventId == "acolor25" && dts_List.getCellData(row, "ADMISU_EXMPT_RSN_CORR_YN") == 'Y') {
        return "#28A0FF";
    } else if (eventId == "acolor26" && dts_List.getCellData(row, "MGT_ISUR_DPND_AXTY_YN") == 'Y') {
        return "#E16A9D";
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
scwin.grd_List2_OnUserColor = function(row, eventId) {
    if (eventId == "acolor20" && dts_List.getCellData(row, "MGT_ISUR_DPND_AXTY_YN") == 'Y') {
        return "#E16A9D";
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
scwin.gform_onload = function() {
    //오늘날짜로 초기화시킨다.
    var today = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_BASE_DD, today);
    rdo_TERM.setValue(Number(eval(today.substring(4, 6)) % 3 - 1));
    if (rdo_TERM.getValue() < 1) {
        rdo_TERM.setValue('2');
    }
    if (scwin.svrGubun == "dr") {
        //DR일 경우 2011.01.28
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
    } else {
        scwin.fn_set_trstatcd();
    }
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    Grd_com_isur.style.zIndex = 30;

    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
};
